{
  "schema": "threatline.threatmodel.v1",
  "issueKey": "EVAL-06",
  "sketch": {
    "components": ["ETL pipeline", "Database service account"],
    "dataStores": ["Production databases"],
    "externalServices": [],
    "trustBoundaries": ["ETL process to production database boundary"],
    "dataClasses": ["credentials"],
    "exposure": "internal",
    "llmFeatures": false
  },
  "threats": [
    {
      "stride": "ElevationOfPrivilege",
      "title": "ETL service account has full admin rights on every production database",
      "scenario": "An attacker who compromises the ETL pipeline (via a malicious dependency, injected job, or stolen credential) inherits a service account with full admin rights across all production databases, letting them read, modify, or delete any data anywhere, not just the tables the ETL needs.",
      "component": "Database service account",
      "likelihood": 3,
      "impact": 5,
      "evidence": [
        { "quote": "the ETL pipeline runs with a database service account that has full admin rights on every production database" }
      ],
      "asvs": ["V4.1.1", "V4.1.3"],
      "cwe": ["CWE-250", "CWE-269"],
      "plainLanguage": "The ETL job's account can do anything to any production database, so if it's ever compromised the damage is total.",
      "requirement": {
        "title": "Restrict ETL service account to least privilege",
        "given": "an ETL pipeline that needs to write to specific tables",
        "when": "the service account is provisioned",
        "then": "it is granted only the minimum schema/table-level permissions required, not admin rights across all databases"
      }
    },
    {
      "stride": "Tampering",
      "title": "Schema changes bypass permission review by design",
      "scenario": "Because the account has admin rights so 'new tables work without permission changes', any developer or compromised script using this ETL path can silently create, alter, or drop tables and schemas in production without any access-control gate, enabling unauthorized structural changes that go unnoticed.",
      "component": "ETL pipeline",
      "likelihood": 3,
      "impact": 4,
      "evidence": [
        { "quote": "so new tables work without permission changes" }
      ],
      "asvs": ["V4.1.1"],
      "cwe": ["CWE-269"],
      "plainLanguage": "The system was set up to skip permission checks for convenience, so anyone using this path can change database structure unchecked.",
      "requirement": {
        "title": "Require explicit approval for schema changes",
        "given": "a new table or schema change is needed",
        "when": "the ETL process attempts the change",
        "then": "it is routed through a permissioned, reviewable process rather than relying on blanket admin rights"
      }
    },
    {
      "stride": "InformationDisclosure",
      "title": "Single admin credential exposes all production databases if leaked",
      "scenario": "Because one service account has admin rights on every production database, a single leaked credential (via logs, config files, or a compromised CI job) gives an attacker read access to all sensitive data across every database, not just the ETL's intended scope.",
      "component": "Database service account",
      "likelihood": 3,
      "impact": 5,
      "evidence": [
        { "quote": "a database service account that has full admin rights on every production database" }
      ],
      "asvs": ["V6.4.1"],
      "cwe": ["CWE-522"],
      "plainLanguage": "One leaked password would expose every production database at once, not just the data the ETL job touches.",
      "requirement": {
        "title": "Scope credentials per data domain",
        "given": "multiple production databases with different sensitivity levels",
        "when": "the ETL pipeline connects to each",
        "then": "it uses separate, narrowly-scoped credentials per database rather than one admin account for all"
      }
    },
    {
      "stride": "Repudiation",
      "title": "Shared admin service account makes actions unattributable",
      "scenario": "Because all ETL operations run under one broad admin service account rather than per-job or per-user identities, any unauthorized or malicious database change made through this account cannot be traced back to a specific job, developer, or compromised process, letting an insider or attacker act without accountability.",
      "component": "Database service account",
      "likelihood": 2,
      "impact": 3,
      "evidence": [
        { "quote": "the ETL pipeline runs with a database service account that has full admin rights on every production database" }
      ],
      "asvs": ["V7.1.1"],
      "cwe": ["CWE-778"],
      "plainLanguage": "Everything the ETL does looks like it came from the same account, so you can't tell who or what actually made a change.",
      "requirement": {
        "title": "Attribute ETL actions to distinct identities",
        "given": "multiple ETL jobs or users triggering database changes",
        "when": "an action is performed against production",
        "then": "it is traceable to the specific job or initiating identity, not just a shared admin account"
      }
    }
  ]
}
